using CustomCodeFramework.Postgres.EntityFramework.Repositories;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Domain.Settings.Entities;using Dhole.Content.Persistence.DbContexts;using Microsoft.EntityFrameworkCore;namespace Dhole.Content.Persistence.Repositories;public sealed class SiteSettingRepository(ServiceDbContext db):EfRepository<SiteSetting,Guid>(db),ISiteSettingRepository{public Task<SiteSetting?> GetByKeyAsync(string siteKey,string key,CancellationToken ct=default){var s=siteKey.Trim();var k=key.Trim();return db.SiteSettings.FirstOrDefaultAsync(x=>x.SiteKey==s&&x.Key==k&&!x.IsDeleted,ct);}public async Task<IReadOnlyCollection<SiteSetting>> GetBySiteAsync(string siteKey,bool publicOnly=false,CancellationToken ct=default){var s=siteKey.Trim();var q=db.SiteSettings.AsNoTracking().Where(x=>x.SiteKey==s&&!x.IsDeleted);if(publicOnly)q=q.Where(x=>x.IsPublic);return await q.OrderBy(x=>x.Key).ToListAsync(ct);}}
